# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"

RSpec.describe "Seed files refuse once a timekeeping handoff has begun" do
  it "refuses both seed files for every company when an unrelated company exists and the global handoff has begun" do
    allow($stdout).to receive(:write)
    create(:company, name: "Unrelated Co")
    TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID).update_columns(monolith_store: "prepared", generation: 2)
    company_count = Company.count
    expect(Company.where(name: ["Fork & Leaf Salads", "Copper Kettle Bakery", "Test Company"]).count).to eq(0)

    # "The ownership record is one global row, so this refusal applies to every company at once."
    expect { load Rails.root.join("db/seeds.rb") }.to raise_error(TimekeepingOwnership::HandoffBegun)
    expect { load Rails.root.join("db/seeds/timesheet_data.rb") }.to raise_error(TimekeepingOwnership::HandoffBegun)

    expect(Company.count).to eq(company_count)
    expect(Company.where(name: ["Fork & Leaf Salads", "Copper Kettle Bakery", "Test Company"]).count).to eq(0)
    expect(TimekeepingOwnership.pluck(:monolith_store, :generation)).to eq([["prepared", 2]])
  end
end
